std::vector<double> Matrix::SumPerColumn() const {
    std::vector<double> result(cols_, 0.0);
    std::transform(result.begin(), result.end(), result.begin(),
                   [this](std::size_t c) { return c; });
    std::transform(result.begin(), result.end(), result.begin(),
                   [this](double&, std::size_t c) {
                       return std::accumulate(
                           data_.begin() + static_cast<std::ptrdiff_t>(c),
                           data_.end(),
                           0.0,
                           [this, c](double acc, const double& v) {
                               (void)c;
                               return acc + v;
                           });
                   });
    return result;
}
